//! End-to-end tests of the textual query language on the production runtime.
#![cfg_attr(rustfmt, rustfmt_skip)]

use std::sync::Arc;

use og_core::{
    engine::Engine,
    query::{parse, PlannerPipeline},
    storage::{CollectionId, DocumentId, MemoryStorage, StorageEngine},
    Document, Value,
};

fn seed(storage: &MemoryStorage, collection: &str, rows: &[&[(&str, Value)]]) {
    let collection = CollectionId::parse(collection).unwrap();
    let mut transaction = storage.begin().unwrap();
    for (index, fields) in rows.iter().enumerate() {
        let id = DocumentId::parse(format!("01900000-0000-7000-8000-{:012x}", index + 1)).unwrap();
        let document = Document::from_fields(fields.iter().map(|(name, value)| (*name, value.clone())));
        transaction.insert(&collection, id, Arc::new(document)).unwrap();
    }
    transaction.commit().unwrap();
}

fn engine() -> Engine {
    let storage = Arc::new(MemoryStorage::new());
    seed(&storage, "users", &[
        &[("name", Value::from("Alice")), ("age", Value::from(31_i64)), ("country", Value::from("FR")), ("active", Value::from(true)), ("balance", Value::from(10_i64))],
        &[("name", Value::from("Bob")), ("age", Value::from(17_i64)), ("country", Value::from("FR")), ("active", Value::from(false)), ("balance", Value::from(-3_i64))],
        &[("name", Value::from("Carol")), ("age", Value::from(45_i64)), ("country", Value::from("DE")), ("active", Value::from(true)), ("balance", Value::from(-12_i64))],
    ]);
    seed(&storage, "orders", &[
        &[("region", Value::from("EU")), ("qty", Value::from(2_i64)), ("price", Value::from(10_i64)), ("status", Value::from("paid"))],
        &[("region", Value::from("EU")), ("qty", Value::from(1_i64)), ("price", Value::from(99_i64)), ("status", Value::from("paid"))],
        &[("region", Value::from("US")), ("qty", Value::from(4_i64)), ("price", Value::from(250_i64)), ("status", Value::from("pending"))],
    ]);
    Engine::new(storage)
}

fn pipeline(text: &str) -> PlannerPipeline {
    let ast = parse(text).unwrap_or_else(|error| panic!("{text}: {error}"));
    PlannerPipeline::from_ast(text, &ast).unwrap_or_else(|error| panic!("{text}: {error}"))
}

/// Runs a read query the way `ogd` does: streaming or governed-blocking, never materialized.
fn stream(engine: &Engine, text: &str) -> Vec<Document> {
    let planned = engine.plan(&pipeline(text)).unwrap_or_else(|error| panic!("{text}: {error}"));
    let mut rows = Vec::new();
    let executed = if engine.supports_governed_blocking_streaming(planned.physical()) {
        engine.stream_governed_blocking_pipeline(planned.physical(), &mut |row| { rows.push(row.document().clone()); Ok(()) })
    } else {
        engine.stream_read_pipeline(planned.physical(), &mut |stored| { rows.push(stored.document().clone()); Ok(()) })
    };
    assert!(executed.unwrap_or_else(|error| panic!("{text}: {error}")).is_some(), "{text}: no bounded executor");
    rows
}

fn materialize(engine: &Engine, text: &str) -> Vec<Document> {
    let result = engine.execute(&pipeline(text)).unwrap_or_else(|error| panic!("{text}: {error}"));
    result.output().rows().iter().map(|row| row.document().clone()).collect()
}

fn names(rows: &[Document]) -> Vec<&str> {
    rows.iter().map(|row| row.get("name").and_then(Value::as_str).unwrap()).collect()
}

#[test] fn symbolic_boolean_operators_match_keywords() { let engine = engine(); for (symbolic, keyword) in [ (r#"on users | where age > 40 || country == "FR""#, r#"on users | where age > 40 or country == "FR""#), (r#"on users | where age >= 18 && active"#, r#"on users | where age >= 18 and active"#), (r#"on users | where !active"#, r#"on users | where not active"#), (r#"on users | where !(age < 18) && country == "FR""#, r#"on users | where not (age < 18) and country == "FR""#), ] { assert_eq!(names(&stream(&engine, symbolic)), names(&stream(&engine, keyword)), "{symbolic}"); } assert_eq!(names(&stream(&engine, r#"on users | where !active"#)), ["Bob"]); }
#[test] fn signed_numeric_literals_are_constants_in_every_stage() { let engine = engine(); assert_eq!(names(&stream(&engine, "on users | where balance > -5")), ["Alice", "Bob"]); assert_eq!(names(&stream(&engine, "on users | where balance <= -12 or age < +18")), ["Bob", "Carol"]); let derived = stream(&engine, r#"on users | where name == "Alice" | derive k = -2 | select k"#); assert_eq!(derived[0].get("k"), Some(&Value::from(-2_i64))); }
#[test] fn compound_group_accepts_several_measures() { let engine = engine(); let rows = stream(&engine, "on orders | group | by region | sum qty as units | sum price as revenue | end"); assert_eq!(rows.len(), 2); let eu = rows.iter().find(|row| row.get("region") == Some(&Value::from("EU"))).unwrap(); assert_eq!(eu.get("units"), Some(&Value::from(3_i64))); assert_eq!(eu.get("revenue"), Some(&Value::from(109_i64))); let counted = stream(&engine, "on orders | group | by status | end | sort count desc"); assert_eq!(counted[0].get("status"), Some(&Value::from("paid"))); }
#[test] fn first_is_a_declared_row_bound_on_every_execution_path() { let engine = engine(); assert_eq!(names(&stream(&engine, "on users | first")), ["Alice"]); assert_eq!(names(&stream(&engine, "on users | skip 1 | first")), ["Bob"]); assert_eq!(names(&materialize(&engine, "on users | first")), ["Alice"]); assert!(stream(&engine, "on users | where age > 100 | first").is_empty()); let projected = stream(&engine, "on users | first country"); assert_eq!(projected.len(), 1); assert!(projected[0].get("name").is_none()); assert_eq!(names(&stream(&engine, "on users | sort age desc | first")), ["Carol"]); let joined = stream(&engine, r#"on users | lookup orders | where status == "paid" | first | into first_paid | end"#); assert_eq!(joined.len(), 3); assert!(joined.iter().all(|row| row.get("first_paid").and_then(Value::as_array).map(<[Value]>::len) == Some(1))); }
#[test] fn expressions_share_one_evaluator_across_stages() { let engine = engine(); assert_eq!(names(&stream(&engine, "on users | where abs(balance) * 2 >= 20 and len(name) <= 5")), ["Alice", "Carol"]); assert_eq!(names(&stream(&engine, r#"on users | where country in ["DE", "IT"] or name not in ["Alice", "Carol"]"#)), ["Bob", "Carol"]); let derived = stream(&engine, r#"on orders | derive total = price * qty, ratio = div(total, qty - 1, 0), kind = if(total > 100, "big", "small") | select total, ratio, kind"#); assert_eq!(derived[0].get("total"), Some(&Value::from(20_i64))); assert_eq!(derived[1].get("ratio"), Some(&Value::from(0_i64))); assert_eq!(derived[2].get("kind"), Some(&Value::from("big"))); let updated = materialize(&engine, r#"on users | where name == "Bob" | set balance = balance * 2 + 1, label = upper(concat(name, "!"))"#); assert_eq!(updated[0].get("balance"), Some(&Value::from(-5_i64))); assert_eq!(updated[0].get("label"), Some(&Value::from("BOB!"))); }
#[test] fn lookup_predicates_correlate_outer_and_inner_documents() { let engine = engine(); seed_extra(&engine); let rows = stream(&engine, r#"on users as u | lookup orders as o | where exists(o.buyer) and o.buyer == u.name and o.status == "paid" | into paid | end"#); let paid = |name: &str| rows.iter().find(|row| row.get("name") == Some(&Value::from(name))).and_then(|row| row.get("paid")).and_then(Value::as_array).map(<[Value]>::len); assert_eq!(paid("Alice"), Some(2)); assert_eq!(paid("Bob"), Some(0)); let materialized = materialize(&engine, r#"on users as u | lookup orders as o | where coalesce(o.buyer, "") == u.name | into all | end"#); assert_eq!(materialized.iter().map(|row| row.get("all").and_then(Value::as_array).map_or(0, <[Value]>::len)).sum::<usize>(), 3); }
#[test] fn single_requires_exactly_one_row_on_every_path() { let engine = engine(); assert_eq!(names(&stream(&engine, r#"on users | where name == "Bob" | single"#)), ["Bob"]); for text in ["on users | single", "on users | where age > 100 | single"] { let planned = engine.plan(&pipeline(text)).unwrap(); assert!(engine.stream_read_pipeline(planned.physical(), &mut |_| Ok(())).is_err(), "{text}"); assert!(engine.execute(&pipeline(text)).is_err(), "{text}"); } }
#[test] fn sample_is_a_bounded_reservoir() { let engine = engine(); let sampled = stream(&engine, "on users | select name | sample 2"); assert_eq!(sampled.len(), 2); assert!(sampled.iter().all(|row| ["Alice", "Bob", "Carol"].contains(&row.get("name").and_then(Value::as_str).unwrap()))); assert_eq!(stream(&engine, "on users | sample 10").len(), 3); assert_eq!(stream(&engine, "on users | sample 3 | limit 1").len(), 1); assert_eq!(materialize(&engine, "on users | sample 2").len(), 2); }

fn seed_extra(engine: &Engine) { for (buyer, status) in [("Alice", "paid"), ("Alice", "paid"), ("Carol", "pending")] { engine.execute(&pipeline(&format!(r#"on orders | insert {{buyer: "{buyer}", status: "{status}", qty: 1, price: 1, region: "EU"}}"#))).unwrap(); } }
#[test] fn unwind_streams_one_row_per_array_item() { let engine = engine(); engine.execute(&pipeline(r#"on orders | insert {region: "EU", tags: ["a", "b", "c"], status: "paid"}"#)).unwrap(); engine.execute(&pipeline(r#"on orders | insert {region: "US", tags: ["d"], status: "paid"}"#)).unwrap(); let tags = |rows: &[Document]| rows.iter().map(|row| row.get("tags").and_then(Value::as_str).unwrap().to_owned()).collect::<Vec<_>>(); for text in ["on orders | where exists(tags) | unwind tags", "on orders | unwind tags | where exists(tags)"] { assert_eq!(tags(&stream(&engine, text)), ["a", "b", "c", "d"], "{text}"); assert_eq!(tags(&materialize(&engine, text)), ["a", "b", "c", "d"], "{text}"); } assert_eq!(tags(&stream(&engine, "on orders | where exists(tags) | unwind tags | skip 1 | limit 2")), ["b", "c"]); assert_eq!(tags(&stream(&engine, "on orders | where exists(tags) | unwind tags | where tags != \"b\" | select tags")), ["a", "c", "d"]); assert_eq!(stream(&engine, "on orders | where exists(tags) | unwind tags | count")[0].get("count"), Some(&Value::from(4_u64))); assert_eq!(tags(&stream(&engine, "on orders | where exists(tags) | unwind tags | sort tags desc | first")), ["d"]); }
#[test] fn unwind_after_a_bound_and_inside_lookup_streams() { let engine = engine(); engine.execute(&pipeline(r#"on orders | insert {region: "EU", tags: ["a", "b"], status: "paid"}"#)).unwrap(); let rows = stream(&engine, "on orders | where exists(tags) | limit 1 | unwind tags"); assert_eq!(rows.len(), 2); let joined = stream(&engine, r#"on users | where name == "Alice" | lookup orders | where exists(tags) | unwind tags | into tags | end"#); assert_eq!(joined[0].get("tags").and_then(Value::as_array).map(<[Value]>::len), Some(2)); }
#[test] fn blocking_stage_accepts_a_streaming_tail() { let engine = engine(); seed_extra(&engine); let same = |text: &str| { let streamed = stream(&engine, text); let materialized = materialize(&engine, text); assert_eq!(streamed, materialized, "{text}"); streamed }; assert_eq!(names(&same("on users | sort name desc | skip 1 | limit 1")), ["Bob"]); assert_eq!(names(&same("on users | sort name | skip 1")), ["Bob", "Carol"]); assert_eq!(names(&same("on users | sort name | skip 5 | limit 2")), Vec::<&str>::new()); assert_eq!(names(&same("on users | sort name | select name | skip 1 | limit 1")), ["Bob"]); let oldest = same("on users | sort age desc | first name"); assert_eq!(oldest.len(), 1); assert!(oldest[0].get("name").is_some() && oldest[0].get("age").is_none()); let grouped = same("on orders | group | by region | sum qty as units | end | select region"); assert_eq!(grouped.len(), 2); assert!(grouped.iter().all(|row| row.get("units").is_none() && row.get("region").is_some())); assert_eq!(same("on orders | group | by region | sum qty as units | end | count")[0].get("count"), Some(&Value::from(2_u64))); let sampled = stream(&engine, "on users | sample 2 | select name"); assert_eq!(sampled.len(), 2); assert!(sampled.iter().all(|row| row.get("age").is_none())); assert_eq!(same("on users | sample 10 | count")[0].get("count"), Some(&Value::from(3_u64))); assert_eq!(same("on users | sort name | where name != \"Bob\" | count")[0].get("count"), Some(&Value::from(2_u64))); assert_eq!(names(&same("on users | sort name | where name != \"Alice\" | limit 1")), ["Bob"]); }
#[test] fn lookup_and_union_accept_a_streaming_tail() { let engine = engine(); seed_extra(&engine); let joined = stream(&engine, r#"on users | lookup orders | where exists(buyer) | into orders | end | select name"#); assert_eq!(joined.len(), 3); assert!(stream(&engine, r#"on users | lookup orders | into orders | end | limit 2"#).len() == 2); assert_eq!(stream(&engine, r#"on users | union | on orders | end | count"#)[0].get("count"), Some(&Value::from(9_u64))); assert_eq!(stream(&engine, r#"on users | union | on orders | end | skip 2 | limit 3"#).len(), 3); }
#[test] fn source_alias_qualifies_fields_at_the_root() { let engine = engine(); for (aliased, plain) in [ ("on users as u | where u.age > 30", "on users | where age > 30"), ("on users as u | where u.age > 30 and u.name != \"Bob\" | sort u.name desc | select u.name", "on users | where age > 30 and name != \"Bob\" | sort name desc | select name"), ("on users as u | where u.name == \"u.age\" or len(u.name) > 3 | select u.name, u.age * 2 as double", "on users | where name == \"u.age\" or len(name) > 3 | select name, age * 2 as double"), ("on users as u | derive twice = u.age * 2 | where u.age > 30 | first", "on users | derive twice = age * 2 | where age > 30 | first") ] { assert_eq!(stream(&engine, aliased), stream(&engine, plain), "{aliased}"); assert_eq!(materialize(&engine, aliased), materialize(&engine, plain), "{aliased}"); } assert!(!stream(&engine, "on users as u | where u.age > 30").is_empty()); seed_extra(&engine); let joined = stream(&engine, r#"on users as u | lookup orders as o | where exists(o.buyer) and o.buyer == u.name | into mine | end | where u.age > 0 | select u.name"#); assert_eq!(joined.len(), 3); }
#[test] fn pivot_values_accept_several_fields_and_expressions() { let engine = engine(); let text = "on orders | pivot | rows region | columns status | values qty, qty * price as revenue, price as unit | aggregate sum | end"; assert_eq!(stream(&engine, text), materialize(&engine, text)); let rows = stream(&engine, text); let eu = rows.iter().find(|row| row.get("region") == Some(&Value::from("EU"))).unwrap(); assert_eq!(eu.get("paid.qty"), Some(&Value::from(3_i64))); assert_eq!(eu.get("paid.revenue"), Some(&Value::from(119_i64))); assert_eq!(eu.get("paid.unit"), Some(&Value::from(109_i64))); let us = rows.iter().find(|row| row.get("region") == Some(&Value::from("US"))).unwrap(); assert_eq!(us.get("pending.revenue"), Some(&Value::from(1000_i64))); /* The hidden field computing the expression never reaches the result. */ assert!(rows.iter().all(|row| row.keys().all(|key| !key.as_str().starts_with("__og_"))), "{rows:?}"); /* One expression measure: cells are named after the column, as for a field. */ let single = stream(&engine, "on orders | pivot | rows region | columns status | values qty * price as revenue | aggregate max | end"); let eu = single.iter().find(|row| row.get("region") == Some(&Value::from("EU"))).unwrap(); assert_eq!(eu.get("paid"), Some(&Value::from(99_i64))); for invalid in ["on orders | pivot | rows region | columns status | values qty * price | aggregate sum | end", "on orders | pivot | rows region | columns status | values qty, qty | aggregate sum | end", "on orders | pivot | rows region | columns status | values qty as n, price as n | aggregate sum | end", "on orders | pivot | rows region | columns status | values qty, price * 2 as qty | aggregate sum | end", "on orders | pivot | rows region | columns status | values qty + as n | aggregate sum | end"] { assert!(engine.plan(&pipeline(invalid)).is_err(), "{invalid}"); } }

#[test] fn pivot_runs_on_a_bounded_incremental_executor() { let engine = engine(); seed_extra(&engine); for text in [ "on orders | pivot | rows region | columns status | values qty | aggregate sum | end", "on orders | where qty >= 1 | pivot | rows region | columns status | values price | aggregate max | end", "on orders | pivot | rows region | columns status | values qty | aggregate count | end" ] { let planned = engine.plan(&pipeline(text)).unwrap(); assert!(engine.supports_governed_blocking_streaming(planned.physical()), "{text}"); assert_eq!(stream(&engine, text), materialize(&engine, text), "{text}"); } let sums = stream(&engine, "on orders | pivot | rows region | columns status | values qty | aggregate sum | end"); assert_eq!(sums.len(), 2); let eu = sums.iter().find(|row| row.get("region") == Some(&Value::from("EU"))).unwrap(); assert_eq!(eu.get("paid"), Some(&Value::from(5_i64))); assert_eq!(eu.get("pending"), Some(&Value::from(1_i64))); }

#[test] fn into_inserts_the_result_into_another_collection() { let engine = engine(); let output = engine.execute(&pipeline(r#"on users | where active == true | into archive"#)).unwrap(); let statistics = output.output().statistics(); assert_eq!((statistics.scanned(), statistics.inserted(), statistics.returned()), (3, 2, 0)); assert!(output.output().rows().is_empty()); assert_eq!(names(&materialize(&engine, "on archive | sort name")), ["Alice", "Carol"]); assert_eq!(materialize(&engine, "on users").len(), 3); }
#[test] fn into_stores_projected_rows_with_fresh_ids_and_leaves_the_source_untouched() { let engine = engine(); engine.execute(&pipeline("on users | select name, _id | into names")).unwrap(); engine.execute(&pipeline("on users | select name | into names")).unwrap(); let stored = materialize(&engine, "on names | sort name"); assert_eq!(names(&stored), ["Alice", "Alice", "Bob", "Bob", "Carol", "Carol"]); assert!(stored.iter().all(|row| !row.contains_key("_id") && !row.contains_key("age"))); let ids = engine.execute(&pipeline("on names")).unwrap().into_parts().1.into_rows().iter().map(|row| row.id().to_string()).collect::<std::collections::BTreeSet<_>>(); assert_eq!(ids.len(), 6); }
#[test] fn into_accepts_aggregated_rows_and_empty_results() { let engine = engine(); engine.execute(&pipeline("on orders | group region | into totals")).unwrap(); assert_eq!(materialize(&engine, "on totals").len(), 2); let output = engine.execute(&pipeline(r#"on users | where age > 100 | into nobody"#)).unwrap(); assert_eq!(output.output().statistics().inserted(), 0); assert!(materialize(&engine, "on nobody").is_empty()); }
#[test] fn into_rejects_invalid_placements_and_targets() { let engine = engine(); for text in ["on users | into archive | limit 1", "on users | delete | into archive", "on users | into a | into b", "on users | into", "on users | into _permissions", "on users | into a b"] { assert!(engine.plan(&pipeline(text)).is_err(), "{text} must not plan"); } for text in ["on users | into users", "on users | limit 1 | into users"] { assert!(engine.execute(&pipeline(text)).is_err(), "{text} must not execute"); } assert_eq!(materialize(&engine, "on users").len(), 3); }
#[test] fn into_is_a_write_and_never_streams_as_a_read() { let engine = engine(); let planned = engine.plan(&pipeline("on users | into archive")).unwrap(); assert!(planned.physical().is_write()); assert!(!planned.physical().is_memory_streaming()); assert!(!engine.supports_governed_blocking_streaming(planned.physical())); }
#[test] fn into_keeps_dotted_collection_names_behind_a_source_alias() { let engine = engine(); engine.execute(&pipeline("on users as u | where u.age > 40 | into u.archive")).unwrap(); assert_eq!(names(&materialize(&engine, "on u.archive")), ["Carol"]); }
#[test] fn into_applies_the_document_scope_to_what_it_writes() { use og_core::query::DocumentScope; let engine = engine(); let scope = DocumentScope::for_place("p1"); let run = |text: &str| { let planned = engine.plan(&pipeline(text)).unwrap(); engine.execute_physical_scoped(planned.physical(), &scope).unwrap() }; assert_eq!(run("on users | into copy").statistics().inserted(), 0); run(r#"on users | insert {name: "Dana"}"#); assert_eq!(run("on users | into copy").statistics().inserted(), 1); let copied = materialize(&engine, "on copy"); assert_eq!(names(&copied), ["Dana"]); assert!(copied[0].iter().any(|(_, value)| value.as_str() == Some("p1"))); }
#[test] fn out_is_an_alias_of_into() { let engine = engine(); assert_eq!(engine.execute(&pipeline("on users | where age > 20 | out adults")).unwrap().output().statistics().inserted(), 2); assert_eq!(names(&materialize(&engine, "on adults | sort name")), ["Alice", "Carol"]); assert!(engine.execute(&pipeline("on users | out users")).is_err()); assert!(engine.plan(&pipeline("on users | out _permissions")).is_err()); let planned = engine.plan(&pipeline("on users as u | out u.copy")).unwrap(); assert!(planned.physical().is_write()); }
#[test] fn into_respects_the_memory_governor() { use og_core::MemoryGovernor; let limited = engine().with_memory_governor(MemoryGovernor::with_limit(64)); let error = limited.execute(&pipeline("on users | into archive")).unwrap_err().to_string(); assert!(error.contains("into"), "{error}"); let limited = limited.with_memory_governor(MemoryGovernor::with_limit(64 * 1024 * 1024)); assert!(materialize(&limited, "on archive").is_empty()); assert_eq!(materialize(&limited, "on users").len(), 3); let roomy = engine().with_memory_governor(MemoryGovernor::with_limit(64 * 1024 * 1024)); assert_eq!(roomy.execute(&pipeline("on users | into archive")).unwrap().output().statistics().inserted(), 3); }

#[test] fn not_binds_looser_than_comparisons_in_queries() { let engine = engine(); assert_eq!(names(&stream(&engine, r#"on users | where not country == "FR""#)), ["Carol"]); assert_eq!(names(&stream(&engine, r#"on users | where not country == "FR" or age < 18"#)), ["Bob", "Carol"]); assert_eq!(names(&stream(&engine, "on users | where age between 18 and 40")), ["Alice"]); assert_eq!(names(&stream(&engine, "on users | where age not between 18 and 40")), ["Bob", "Carol"]); }
#[test] fn optional_paths_tolerate_heterogeneous_documents() { let engine = engine(); engine.execute(&pipeline(r#"on users | where name == "Bob" | set nick = "B""#)).unwrap(); assert_eq!(names(&stream(&engine, r#"on users | where nick? == "B""#)), ["Bob"]); let rows = stream(&engine, "on users | select name, coalesce(nick?, name) as display"); assert_eq!(rows.iter().map(|row| row.get("display").and_then(Value::as_str).unwrap()).collect::<Vec<_>>(), ["Alice", "B", "Carol"]); assert!(engine.plan(&pipeline("on users | where nick == \"B\"")).is_ok()); }
#[test] fn sort_accepts_computed_keys_and_stays_bounded() { let engine = engine(); for text in ["on orders | sort price * qty desc | limit 2", "on orders | sort price * qty desc | first"] { let planned = engine.plan(&pipeline(text)).unwrap(); assert!(engine.supports_governed_blocking_streaming(planned.physical()), "{text}"); } let rows = stream(&engine, "on orders | sort price * qty desc, region | limit 2"); assert_eq!(rows.iter().map(|row| row.get("price").cloned().unwrap()).collect::<Vec<_>>(), [Value::from(250_i64), Value::from(99_i64)]); assert!(rows.iter().all(|row| !row.iter().any(|(name, _)| name.as_str().starts_with("__og_sort")))); assert_eq!(stream(&engine, "on orders | sort price * qty desc | limit 2"), materialize(&engine, "on orders | sort price * qty desc | limit 2")); assert_eq!(names(&stream(&engine, "on users | sort len(name) desc, name | limit 1")), ["Alice"]); }
#[test] fn group_measures_go_beyond_sum_on_every_path() { let engine = engine(); let text = "on orders | group | by region | sum qty as units | avg price as mean | min price as low | max qty | first status | last status | count as rows | count qty as priced | end"; let streamed = stream(&engine, text); assert_eq!(streamed, materialize(&engine, text)); let eu = streamed.iter().find(|row| row.get("region") == Some(&Value::from("EU"))).unwrap(); assert_eq!(eu.get("units"), Some(&Value::from(3_i64))); assert_eq!(eu.get("mean"), Some(&Value::float(54.5).unwrap())); assert_eq!(eu.get("low"), Some(&Value::from(10_i64))); assert_eq!(eu.get("max_qty"), Some(&Value::from(2_i64))); assert_eq!(eu.get("first_status"), Some(&Value::from("paid"))); assert_eq!(eu.get("rows"), Some(&Value::from(2_u64))); assert_eq!(eu.get("priced"), Some(&Value::from(2_u64))); assert!(engine.plan(&pipeline("on orders | group | by region | median qty | end")).is_err()); }
#[test] fn bucket_counts_rows_per_range() { let engine = engine(); let rows = stream(&engine, r#"on users | bucket age by [0, 18, 40] default "other" as band"#); let bands = rows.iter().map(|row| (row.get("band").cloned().unwrap(), row.get("count").cloned().unwrap())).collect::<Vec<_>>(); assert!(bands.contains(&(Value::from(0_i64), Value::from(1_u64)))); assert!(bands.contains(&(Value::from(18_i64), Value::from(1_u64)))); assert!(bands.contains(&(Value::from("other"), Value::from(1_u64)))); assert_eq!(stream(&engine, "on users | bucket age by [0, 100]")[0].get("bucket"), Some(&Value::from(0_i64))); assert!(engine.plan(&pipeline("on users | bucket age")).is_err()); }
#[test] fn one_line_lookup_joins_on_equality() { let engine = engine(); seed_extra(&engine); for text in [r#"on users | lookup orders on buyer == name into mine"#, r#"on users as u | lookup orders as o on o.buyer == u.name into mine"#] { let rows = stream(&engine, text); let mine = |name: &str| rows.iter().find(|row| row.get("name") == Some(&Value::from(name))).and_then(|row| row.get("mine")).and_then(Value::as_array).map(<[Value]>::len); assert_eq!((mine("Alice"), mine("Bob"), mine("Carol")), (Some(2), Some(0), Some(1)), "{text}"); assert_eq!(rows, materialize(&engine, text), "{text}"); } assert!(engine.plan(&pipeline("on users | lookup orders on buyer into mine")).is_err()); }
#[test] fn insert_accepts_a_batch() { let engine = engine(); let output = engine.execute(&pipeline(r#"on batch | insert [{name: "a", n: 1}, {"name": "b", "n": 2.5, "tags": ["x"]}]"#)).unwrap(); assert_eq!(output.output().statistics().inserted(), 2); let rows = materialize(&engine, "on batch | sort name"); assert_eq!(rows.len(), 2); assert_eq!(rows[1].get("n"), Some(&Value::float(2.5).unwrap())); assert!(engine.plan(&pipeline("on batch | insert []")).is_err()); assert!(engine.plan(&pipeline("on batch | insert [1, 2]")).is_err()); }
#[test] fn unwind_exposes_index_and_keeps_empty_arrays_on_request() { let engine = engine(); engine.execute(&pipeline(r#"on bags | insert [{bag: 1, items: ["a", "b"]}, {bag: 2, items: []}, {bag: 3}]"#)).unwrap(); let rows = stream(&engine, "on bags | unwind items with index position"); assert_eq!(rows.len(), 3); assert_eq!(rows[1].get("position"), Some(&Value::from(1_u64))); assert_eq!(rows[2].get("position"), Some(&Value::null())); let kept = stream(&engine, "on bags | unwind items keep empty"); assert_eq!(kept.len(), 4); assert_eq!(kept[2].get("items"), Some(&Value::null())); assert!(engine.plan(&pipeline("on bags | unwind items sideways")).is_err()); }
#[test] fn explain_describes_the_plan_without_running_it() { let engine = engine(); let plan = engine.explain(&pipeline(r#"on orders | where qty > 1 | group | by region | avg price as mean | end | sort mean desc"#)).unwrap(); assert_eq!(plan.get("collection"), Some(&Value::from("orders"))); assert_eq!(plan.get("executor"), Some(&Value::from("governed_blocking"))); assert_eq!(plan.get("read_only"), Some(&Value::from(true))); let operators = plan.get("operators").and_then(Value::as_array).unwrap(); assert_eq!(operators[0].as_object().and_then(|operator| operator.get("detail")), Some(&Value::from("qty > 1"))); assert_eq!(operators[1].as_object().and_then(|operator| operator.get("detail")), Some(&Value::from("region, avg(price) as mean"))); let write = engine.explain(&pipeline("on orders | delete")).unwrap(); assert_eq!(write.get("executor"), Some(&Value::from("transactional"))); assert_eq!(materialize(&engine, "on orders").len(), 3); }
#[test] fn let_variables_are_reused_across_stages() { let engine = engine(); let text = og_core::query::prepare_query(r#"let $adult = 18, $origin = "FR" | let $label = concat("from ", $origin) | on users | where age >= $adult and country == $origin | derive tag = $label | select name, tag"#, &serde_json::Map::new()).unwrap(); let rows = stream(&engine, &text); assert_eq!(names(&rows), ["Alice"]); assert_eq!(rows[0].get("tag"), Some(&Value::from("from FR"))); }
#[test] fn top_n_reaches_through_row_preserving_stages() { let engine = engine(); seed_extra(&engine); let strategies = |text: &str| { let planned = engine.plan(&pipeline(text)).unwrap(); assert!(engine.supports_governed_blocking_streaming(planned.physical()), "{text}"); engine.stream_governed_blocking_pipeline(planned.physical(), &mut |_| Ok(())).unwrap().unwrap().strategies() }; for text in ["on orders | sort price * qty desc | limit 2", "on orders | sort price desc | derive total = price * qty | limit 2", "on orders | sort price desc | rename region as zone | drop status | first", "on orders | sort price desc | select price * 2 as double | skip 1 | limit 2"] { assert!(strategies(text).contains(og_core::query::ExecutionStrategy::TopN), "{text}"); assert_eq!(stream(&engine, text), materialize(&engine, text), "{text}"); } let top = stream(&engine, "on orders | sort price * qty desc | limit 2"); assert_eq!(top.iter().map(|row| row.get("price").cloned().unwrap()).collect::<Vec<_>>(), [Value::from(250_i64), Value::from(99_i64)]); }
#[test] fn bounds_are_not_pushed_past_row_filters() { let engine = engine(); for row in [r#"{n: 1}"#, r#"{n: 2}"#, r#"{n: 3, e: [1.0, 0.0]}"#, r#"{n: 4, e: [0.0, 1.0]}"#] { engine.execute(&pipeline(&format!("on vectors | insert {row}"))).unwrap(); } let text = "on vectors | sort n | near e, [1.0, 0.0] | limit 2"; let rows = stream(&engine, text); assert_eq!(rows.iter().map(|row| row.get("n").cloned().unwrap()).collect::<Vec<_>>(), [Value::from(3_u64), Value::from(4_u64)]); assert_eq!(rows, materialize(&engine, text)); }
#[test] fn compiled_stages_keep_their_runtime_errors() { let engine = engine(); assert!(stream(&engine, "on nothing_here | derive total = price *").is_empty()); let planned = engine.plan(&pipeline("on orders | derive total = price *")).unwrap(); assert!(engine.stream_read_pipeline(planned.physical(), &mut |_| Ok(())).unwrap_err().to_string().contains("invalid derive expression")); }
#[test] fn stages_reading_the_id_still_see_it() { let engine = engine(); for text in [r#"on users | where _id != "x" and age > 30 | derive copy = _id | select copy, name"#, r#"on users | where age > 30 | select concat(_id, "") as copy, name"#, r#"on users | sort name | derive copy = _id | limit 2"#] { let rows = stream(&engine, text); assert!(!rows.is_empty(), "{text}"); assert!(rows.iter().all(|row| row.get("copy").and_then(Value::as_str).is_some_and(|id| id.len() == 36)), "{text}"); assert_eq!(rows, materialize(&engine, text), "{text}"); } }
#[test] fn hash_join_matches_the_nested_loop_exactly() { let engine = engine(); for row in [r#"{k: 1, tag: "int"}"#, r#"{k: 1.0, tag: "float"}"#, r#"{k: null, tag: "null"}"#, r#"{tag: "missing"}"#, r#"{k: 2, tag: "two"}"#, r#"{k: 1, tag: "int-bis"}"#] { engine.execute(&pipeline(&format!("on keys | insert {row}"))).unwrap(); } for row in [r#"{name: "one", key: 1}"#, r#"{name: "nothing", key: null}"#, r#"{name: "none"}"#, r#"{name: "three", key: 3}"#] { engine.execute(&pipeline(&format!("on probes | insert {row}"))).unwrap(); } let strategies = |text: &str| { let planned = engine.plan(&pipeline(text)).unwrap(); engine.stream_governed_blocking_pipeline(planned.physical(), &mut |_| Ok(())).unwrap().unwrap().strategies() }; let tags = |rows: &[Document], name: &str| rows.iter().find(|row| row.get("name") == Some(&Value::from(name))).and_then(|row| row.get("hits")).and_then(Value::as_array).unwrap().iter().map(|hit| hit.as_object().and_then(|hit| hit.get("tag")).and_then(Value::as_str).unwrap().to_owned()).collect::<Vec<_>>(); for text in ["on probes | lookup keys on k == key into hits", "on probes as p | lookup keys as o | where exists(o.k) and exists(p.key) and o.k == p.key | into hits | end", "on probes as p | lookup keys as o | where exists(o.k) and exists(p.key) and o.k == p.key | first | into hits | end", "on probes as p | lookup keys as o | where exists(o.k) and exists(p.key) and p.key == o.k and o.tag != \"int\" | into hits | end"] { let streamed = stream(&engine, text); assert_eq!(streamed, materialize(&engine, text), "{text}"); assert!(strategies(text).contains(og_core::query::ExecutionStrategy::HashJoin), "{text}"); } let rows = stream(&engine, "on probes | lookup keys on k == key into hits"); assert_eq!(tags(&rows, "one"), ["int", "float", "int-bis"]); assert_eq!(tags(&rows, "nothing"), ["null"], "null == null matches, like the nested loop"); assert!(tags(&rows, "none").is_empty() && tags(&rows, "three").is_empty()); assert_eq!(tags(&stream(&engine, "on probes as p | lookup keys as o | where exists(o.k) and exists(p.key) and o.k == p.key | first | into hits | end"), "one"), ["int"]); /* Unguarded correlations fail on a missing key, with or without the index. */ let text = "on probes as p | lookup keys as o | where o.k == p.key | into hits | end"; let planned = engine.plan(&pipeline(text)).unwrap(); assert!(engine.stream_governed_blocking_pipeline(planned.physical(), &mut |_| Ok(())).is_err()); assert!(engine.execute(&pipeline(text)).is_err()); /* A number meeting a string raises the comparison error on both paths. */ engine.execute(&pipeline(r#"on keys | insert {k: "1", tag: "text"}"#)).unwrap(); let text = "on probes as p | lookup keys as o | where exists(o.k) and exists(p.key) and o.k == p.key | into hits | end"; let planned = engine.plan(&pipeline(text)).unwrap(); let streamed = engine.stream_governed_blocking_pipeline(planned.physical(), &mut |_| Ok(())).unwrap_err().to_string(); let materialized = engine.execute(&pipeline(text)).unwrap_err().to_string(); assert!(streamed.contains("incompatible") && materialized.contains("incompatible"), "{streamed} / {materialized}"); }
#[test] fn writes_stream_the_rows_their_read_keeps() { let engine = engine(); assert_eq!(engine.execute(&pipeline("on users | sort age desc | limit 2 | set seen = true")).unwrap().output().statistics().replaced(), 2); assert_eq!(names(&stream(&engine, "on users | where seen? == true | sort name")), ["Alice", "Carol"]); assert_eq!(engine.execute(&pipeline("on users | where seen? == true | sort age | limit 1 | delete")).unwrap().output().statistics().deleted(), 1); assert_eq!(names(&stream(&engine, "on users | sort name")), ["Bob", "Carol"]); }
#[test] fn writes_refuse_merged_rows_and_later_blocking_stages() { let engine = engine(); for text in ["on users | group country | set x = 1", "on users | count | delete", "on users | set x = 1 | sort age", "on users | distinct country | delete"] { assert!(engine.execute(&pipeline(text)).is_err(), "{text}"); } assert_eq!(stream(&engine, "on users | where x? == 1").len(), 0); assert_eq!(stream(&engine, "on users").len(), 3); }



#[test] fn lookup_runs_blocking_stages_on_the_rows_it_joins() { let engine = engine(); seed_extra(&engine); let counts = |text: &str| stream(&engine, text).iter().map(|row| (row.get("name").and_then(Value::as_str).unwrap().to_owned(), row.get("n").cloned().unwrap())).collect::<Vec<_>>(); assert_eq!(counts(r#"on users as u | lookup orders as o | where exists(o.buyer) and o.buyer == u.name | group status | into statuses | end | select name, len(statuses) as n | sort name"#), [("Alice".to_owned(), Value::from(1_u64)), ("Bob".to_owned(), Value::from(0_u64)), ("Carol".to_owned(), Value::from(1_u64))]); let top = stream(&engine, r#"on users | lookup orders as o | where o.region == "EU" | sort price desc | limit 1 | into top | end | select top"#); assert_eq!(top.len(), 3); assert!(top.iter().all(|row| row.get("top") == Some(&Value::array([Value::object(stream(&engine, r#"on orders | where region == "EU" | sort price desc | first"#)[0].clone())]))), "{top:?}"); }
#[test] fn group_measures_take_expressions_predicates_and_orders() { let engine = engine(); let text = r#"on orders | group | by region | sum qty * price as revenue | sum qty where status == "paid" as paid | count where price > 50 as dear | last status by price as dearest | first price by qty as smallest | first price by qty where status == "pending" as pending | max qty * 2 as twice | end"#; let streamed = stream(&engine, text); assert_eq!(streamed, materialize(&engine, text)); let get = |region: &str, field: &str| streamed.iter().find(|row| row.get("region") == Some(&Value::from(region))).unwrap().get(field).cloned(); assert_eq!([get("EU", "revenue"), get("EU", "paid"), get("EU", "dear"), get("EU", "dearest"), get("EU", "smallest"), get("EU", "pending"), get("EU", "twice")], [Some(Value::from(119_i64)), Some(Value::from(3_i64)), Some(Value::from(1_u64)), Some(Value::from("paid")), Some(Value::from(99_i64)), Some(Value::null()), Some(Value::from(4_i64))]); assert_eq!([get("US", "revenue"), get("US", "paid"), get("US", "dearest"), get("US", "pending")], [Some(Value::from(1000_i64)), None, Some(Value::from("pending")), Some(Value::from(250_i64))]); let ties = stream(&engine, "on users | group | by country | first name by country as f | last name by country as l | end"); assert_eq!(ties.iter().map(|row| (row.get("f").cloned(), row.get("l").cloned())).collect::<Vec<_>>(), [(Some(Value::from("Carol")), Some(Value::from("Carol"))), (Some(Value::from("Alice")), Some(Value::from("Bob")))]); for (wrong, message) in [("sum qty * price", "needs `as <alias>`"), ("sum qty by price as s", "takes no `by"), ("first status where qty > 1 as f", "needs `by <order>`"), ("sum qty where qty > as s", "invalid expression")] { let error = engine.plan(&pipeline(&format!("on orders | group | by region | {wrong} | end"))).map(drop).unwrap_err().to_string(); assert!(error.contains(message), "{wrong}: {error}"); } }
#[test] fn fiscal_functions_name_the_year_a_fiscal_year_closes_in() { let engine = engine(); let rows = stream(&engine, r#"on users | where name == "Alice" | select fiscal_year("2026-06-30", 6) as y, fiscal_year("2026-07-01", 6) as next, fiscal_month("2026-07-01", 6) as m, date_format(fiscal_start("2026-03-15", 6), "%F") as start, date_format(fiscal_end("2026-03-15", 6), "%F") as end, fiscal_year(parse_date("2026-12-31"), 12) as calendar, fiscal_month("2026-07-01", "2018-07-01") as opened"#); let get = |field: &str| rows[0].get(field).cloned().unwrap(); assert_eq!([get("y"), get("next"), get("m"), get("start"), get("end"), get("calendar"), get("opened")], [Value::from(2026_i64), Value::from(2027_i64), Value::from(1_i64), Value::from("2025-07-01"), Value::from("2026-06-30"), Value::from(2026_i64), Value::from(1_i64)]); for wrong in [r#"fiscal_year("2026-01-01", 13)"#, r#"fiscal_month("2026-01-01", "june")"#, r#"fiscal_end("2026-01-01", "2025-07-15")"#, r#"fiscal_start("soon", 6)"#] { let text = format!("on users | select {wrong} as x"); let planned = engine.plan(&pipeline(&text)).unwrap(); assert!(engine.stream_read_pipeline(planned.physical(), &mut |_| Ok(())).is_err(), "{wrong}"); } }
#[test] fn window_adds_values_over_ordered_partitions() { let engine = engine(); let text = "on orders | window | partition by region | order by price | lag price as prev | lead qty as next | cumsum qty as running | first price as low | last price as high | row_number as n | end"; let rows = stream(&engine, text); assert_eq!(rows, materialize(&engine, text)); let fields = |row: &Document| ["region", "price", "prev", "next", "running", "low", "high", "n"].map(|field| row.get(field).cloned().unwrap_or_else(|| panic!("{field}: {row:?}"))); assert_eq!(rows.iter().map(fields).collect::<Vec<_>>(), [[Value::from("EU"), Value::from(10_i64), Value::null(), Value::from(1_i64), Value::from(2_i64), Value::from(10_i64), Value::from(99_i64), Value::from(1_u64)], [Value::from("EU"), Value::from(99_i64), Value::from(10_i64), Value::null(), Value::from(3_i64), Value::from(10_i64), Value::from(99_i64), Value::from(2_u64)], [Value::from("US"), Value::from(250_i64), Value::null(), Value::null(), Value::from(4_i64), Value::from(250_i64), Value::from(250_i64), Value::from(1_u64)]]); let lagged = stream(&engine, "on orders | window | order by price desc | lag price 2 as p2 | end | select price, p2"); assert_eq!(lagged.iter().map(|row| row.get("p2").cloned()).collect::<Vec<_>>(), [Some(Value::null()), Some(Value::null()), Some(Value::from(250_i64))]); assert_eq!(stream(&engine, "on orders | window | partition by region | order by price | row_number | end | where row_number == 1 | count")[0].get("count"), Some(&Value::from(2_u64))); for (wrong, message) in [("window | partition by region | lag price | end", "requires directive \"order\""), ("window | order by price | sum qty | end", "window accepts"), ("window | order by price | lag price 0 | end", "expected `lag <field>"), ("window | order by price | end", "needs at least one function"), ("window | order by price | order by qty | lag price | end", "order")] { let error = engine.plan(&pipeline(&format!("on orders | {wrong}"))).map(drop).unwrap_err().to_string(); assert!(error.contains(message), "{wrong}: {error}"); } }
#[test] fn window_partitions_follow_the_sort_equality_of_numbers() { let engine = engine(); engine.execute(&pipeline("on mixed | insert [{k: 1, v: 1}, {k: 1.0, v: 2}, {k: 1, v: 3}, {k: 2, v: 4}]")).unwrap(); let rows = stream(&engine, "on mixed | window | partition by k | order by v | row_number as n | cumsum v as c | end"); assert_eq!(rows.iter().map(|row| (row.get("n").cloned().unwrap(), row.get("c").cloned().unwrap())).collect::<Vec<_>>(), [(Value::from(1_u64), Value::from(1_i64)), (Value::from(2_u64), Value::from(3_i64)), (Value::from(3_u64), Value::from(6_i64)), (Value::from(1_u64), Value::from(4_i64))]); }
#[test] fn fill_adds_the_rows_a_grid_misses_in_each_partition() { let engine = engine(); engine.execute(&pipeline(r#"on ledger | insert [{entity: "A", month: "2026-01", balance: 5}, {entity: "A", month: "2026-03", balance: 7}, {entity: "A", month: "2025-12", balance: 1}, {entity: "B", month: "2026-02", balance: 3}, {month: "2026-01"}]"#)).unwrap(); let text = r#"on ledger | fill month from "2026-01" to "2026-04" step "month" by entity with balance = 0"#; let rows = stream(&engine, text); assert_eq!(rows, materialize(&engine, text)); let cell = |row: &Document, field: &str| row.get(field).map_or("-".to_owned(), |value| og_core::helpers::value_to_json(value).to_string()); assert_eq!(rows.iter().map(|row| format!("{} {} {}", cell(row, "entity"), cell(row, "month"), cell(row, "balance"))).collect::<Vec<_>>(), [r#"- "2026-01" -"#, r#"- "2026-02" 0"#, r#"- "2026-03" 0"#, r#"- "2026-04" 0"#, r#""A" "2025-12" 1"#, r#""A" "2026-01" 5"#, r#""A" "2026-02" 0"#, r#""A" "2026-03" 7"#, r#""A" "2026-04" 0"#, r#""B" "2026-01" 0"#, r#""B" "2026-02" 3"#, r#""B" "2026-03" 0"#, r#""B" "2026-04" 0"#]); assert_eq!(stream(&engine, "on users | where name == \"Bob\" | select age | fill age from 1 to 30 step 8").iter().map(|row| row.get("age").cloned().unwrap()).collect::<Vec<_>>(), [1_i64, 9, 17, 25].map(Value::from)); assert_eq!(stream(&engine, r#"on ledger | fill month from "2026-01-01" to "2026-03-01" step "month" | count"#)[0].get("count"), Some(&Value::from(8_u64))); for (wrong, message) in [(r#"fill month from "2026-01" to "2026-04" step "fortnight""#, "unknown date unit"), ("fill age from 1 to 3 step 0", "positive"), ("fill age from 1 to 1000000 step 1", "at most 100000"), ("fill age from 1 step 1", "expected `fill"), (r#"lookup ledger | fill month from "2026-01" to "2026-02" step "month" | into l | end"#, "top level")] { let error = engine.plan(&pipeline(&format!("on users | {wrong}"))).map(drop).unwrap_err().to_string(); assert!(error.contains(message), "{wrong}: {error}"); } }
#[test] fn sorting_values_of_different_kinds_fails_without_panicking() { let engine = engine(); engine.execute(&pipeline(r#"on kinds | insert [{k: 1}, {k: "a"}, {k: [1]}, {k: {x: 1}}, {k: 2}, {k: "b"}, {k: true}, {k: 3}, {k: [2]}, {k: "c"}, {k: 4}, {k: {y: 2}}, {k: 5}, {k: "d"}, {k: 6}, {k: [3]}, {k: 7}, {k: "e"}, {k: 8}, {k: 9}, {k: "f"}, {k: 10}]"#)).unwrap(); let planned = engine.plan(&pipeline("on kinds | sort k")).unwrap(); let error = engine.stream_governed_blocking_pipeline(planned.physical(), &mut |_| Ok(())).unwrap_err().to_string(); assert!(error.contains("cannot sort field k: its values must all be"), "{error}"); }
#[test] fn lookup_stages_read_both_aliases_like_its_where() { let engine = engine(); for text in ["on users as u | where name == \"Alice\" | lookup orders as o | where o.qty >= 1 | derive total = o.qty * price, owner = u.name, here = o.region | select o.region, total, owner, here, u.country as country | into orders | end", "on users as u | where name == \"Alice\" | lookup orders as o | where o.region == \"EU\" and u.country == \"FR\" | derive total = o.qty * price, owner = u.name, here = o.region | select o.region, total, owner, here, u.country as country | into orders | end"] { let rows = stream(&engine, text); let orders = rows[0].get("orders").and_then(Value::as_array).unwrap_or_else(|| panic!("{text}: {rows:?}")); let eu = orders.iter().filter_map(Value::as_object).filter(|order| order.get("here") == Some(&Value::from("EU"))).map(|order| (order.get("total").cloned(), order.get("owner").cloned(), order.get("country").cloned(), order.get("region").cloned())).collect::<Vec<_>>(); assert_eq!(eu, [(Some(Value::from(20_i64)), Some(Value::from("Alice")), Some(Value::from("FR")), Some(Value::from("EU"))), (Some(Value::from(99_i64)), Some(Value::from("Alice")), Some(Value::from("FR")), Some(Value::from("EU")))], "{text}"); } }
#[test] fn composite_lookup_keys_match_the_nested_loop_exactly() { let engine = engine(); engine.execute(&pipeline(r#"on staged | insert [{e: "E1", d: 1, v: "x"}, {e: "E1", d: 2}, {e: "E2", d: 1.0}, {e: "E2", d: 1}, {d: 1}]"#)).unwrap(); engine.execute(&pipeline(r#"on stored | insert [{e: "E1", d: 1, v: "x", n: 1}, {e: "E1", d: 2, n: 2}, {e: "E1", d: 2, v: "y", n: 3}, {e: "E2", d: 1, n: 4}, {e: "E3", d: 1, n: 5}]"#)).unwrap(); let strategies = |text: &str| { let planned = engine.plan(&pipeline(text)).unwrap(); engine.stream_governed_blocking_pipeline(planned.physical(), &mut |_| Ok(())).unwrap().unwrap().strategies() }; let text = "on stored as t | lookup staged as s | where s.e? == t.e and s.d == t.d and s.v? == t.v? | into same | end | derive same = len(same) | select n, same | sort n"; let rows = stream(&engine, text); assert_eq!((rows.clone(), strategies(text).contains(og_core::query::ExecutionStrategy::HashJoin)), (materialize(&engine, text), true)); assert_eq!(rows.iter().map(|row| row.get("same").cloned().unwrap()).collect::<Vec<_>>(), [1, 1, 0, 2, 0].map(|n: u64| Value::from(n))); engine.execute(&pipeline(r#"on staged | insert {e: "E1", d: "2"}"#)).unwrap(); let text = "on stored as t | lookup staged as s | where s.e? == t.e and s.d == t.d | into same | end"; let planned = engine.plan(&pipeline(text)).unwrap(); assert!(engine.stream_governed_blocking_pipeline(planned.physical(), &mut |_| Ok(())).unwrap_err().to_string().contains("incompatible") && engine.execute(&pipeline(text)).unwrap_err().to_string().contains("incompatible")); }
#[test] fn prefix_lookup_matches_the_nested_loop_exactly() { let engine = engine(); engine.execute(&pipeline(r#"on rules | insert [{prefix: "6", c: "a"}, {prefix: "60", c: "b"}, {prefix: "601", c: "c"}, {prefix: "601", c: "c2"}, {prefix: "7", c: "d"}, {prefix: "é", c: "e"}, {prefix: "", c: "all"}]"#)).unwrap(); engine.execute(&pipeline(r#"on odd | insert [{prefix: "6", c: "a"}, {prefix: 6, c: "number"}, {c: "missing"}]"#)).unwrap(); engine.execute(&pipeline(r#"on accounts | insert [{account: "6011"}, {account: "602"}, {account: "6"}, {account: "5"}, {account: "éa"}, {account: ""}, {account: "601"}]"#)).unwrap(); let outcome = |text: &str| { let planned = engine.plan(&pipeline(text)).map_err(|error| error.to_string())?; let mut rows = Vec::new(); let statistics = engine.stream_governed_blocking_pipeline(planned.physical(), &mut |row| { rows.push(row.document().clone()); Ok(()) }).map_err(|error| error.to_string())?.unwrap(); Ok::<_, String>((rows, statistics.strategies().contains(og_core::query::ExecutionStrategy::HashJoin))) }; for (collection, tail) in [("rules", "| derive l = len(prefix) | sort l desc, c | select c | into hits | end"), ("rules", "| first | into hits | end"), ("odd", "| select c | into hits | end")] { let query = |predicate: &str| format!("on accounts as a | lookup {collection} as r | where {predicate} {tail}"); let indexed = outcome(&query("starts_with(a.account, r.prefix)")); let scanned = outcome(&query("true and starts_with(a.account, r.prefix)")); assert_eq!(indexed.as_ref().map(|(rows, _)| rows), scanned.as_ref().map(|(rows, _)| rows), "{collection} {tail}"); if collection == "rules" { assert!(indexed.as_ref().is_ok_and(|(rows, hashed)| *hashed && rows.len() == 7), "{indexed:?}"); } else { assert!(indexed.is_err()); } } }
#[test] fn memoized_lookups_key_on_every_outer_field_they_read() { let engine = engine(); engine.execute(&pipeline(r#"on rules | insert [{prefix: "60", c: "b"}, {prefix: "601", c: "c"}]"#)).unwrap(); engine.execute(&pipeline(r#"on accounts | insert [{account: "6011", entity: "X"}, {account: "6011", entity: "Y"}, {account: "6011", entity: "X"}, {account: "602", entity: "Y"}]"#)).unwrap(); let owners = |text: &str| stream(&engine, text).iter().map(|row| row.get("hits").and_then(Value::as_array).unwrap().iter().map(|hit| format!("{}{}", hit.as_object().unwrap().get("c").and_then(Value::as_str).unwrap(), hit.as_object().unwrap().get("owner").and_then(Value::as_str).unwrap_or("-"))).collect::<Vec<_>>().join(",")).collect::<Vec<_>>(); assert_eq!(owners("on accounts as a | lookup rules as r | where starts_with(a.account, r.prefix) | derive owner = a.entity | select c, owner | into hits | end"), ["bX,cX", "bY,cY", "bX,cX", "bY"]); assert_eq!(owners("on accounts as a | lookup rules as r | where starts_with(a.account, r.prefix) and a.entity == \"X\" | into hits | end"), ["b-,c-", "", "b-,c-", ""]); assert_eq!(stream(&engine, "on accounts as a | lookup rules as r | where starts_with(a.account, r.prefix) and now() > 0 | derive t = now() | into hits | end").len(), 4); }
#[test] fn pivot_feeds_the_stages_after_it() { let engine = engine(); let text = "on orders | pivot | rows region | columns status | values qty | aggregate sum | end | derive total = coalesce(paid?, 0) + coalesce(pending?, 0) | sort total desc | select region, total"; for rows in [stream(&engine, text), materialize(&engine, text)] { assert_eq!(rows.iter().map(|row| (row.get("region").and_then(Value::as_str).unwrap(), row.get("total").cloned().unwrap())).collect::<Vec<_>>(), [("US", Value::from(4_i64)), ("EU", Value::from(3_i64))]); } }
fn filter_index(engine: &Engine, text: &str) -> Vec<usize> { engine.plan(&pipeline(text)).unwrap_or_else(|error| panic!("{text}: {error}")).physical().operators().iter().enumerate().filter(|(_, operator)| operator.predicate().is_some()).map(|(index, _)| index).collect() }
#[test] fn filters_move_before_stages_that_leave_their_fields_and_rows_alone() { let engine = engine(); for (text, at) in [("on orders | derive t = qty * price | sort t | where region == \"EU\"", vec![0]), ("on orders | group | by region, status | sum qty as q | end | where region == \"EU\"", vec![0]), ("on orders | window | partition by region | order by qty | cumsum qty as c | end | where region == \"EU\"", vec![0]), ("on orders | derive tags = [1, 2] | unwind tags | select region, tags | where region == \"EU\"", vec![0]), ("on orders | lookup users as u | where u.country == \"FR\" | into buyers | end | where region == \"EU\"", vec![0]), ("on orders | where qty > 1 | derive t = 1 | where region == \"EU\"", vec![0, 1, 2]), ("on orders | derive region = \"X\" | where region == \"EU\"", vec![1]), ("on orders | where region == \"EU\" and qty > 1", vec![0]), ("on orders | where qty > 1 | derive t = 1 | where region == \"EU\" and status == \"paid\"", vec![0, 1, 2, 3]), ("on orders | limit 2 | where region == \"EU\"", vec![1]), ("on orders | group | by region | sum qty as q | end | where q > 2", vec![1]), ("on orders | window | partition by region | order by qty | cumsum qty as c | end | where qty > 1", vec![2]), ("on orders | select region as r | where r == \"EU\"", vec![1]), ("on orders | derive region = if(false, null, region) | where region == \"EU\"", vec![0]), ("on orders | derive region = if(true, null, region) | where region == \"EU\"", vec![1]), ("on orders | union | on orders | end | where region == \"EU\"", vec![0]), ("on orders | union | on orders as o | end | where o.region == \"EU\"", vec![1])] { assert_eq!(filter_index(&engine, text), at, "{text}"); } assert_eq!(stream(&engine, "on orders | group | by region | sum qty as q | end | where region == \"EU\"").len(), 1); engine.execute(&pipeline("on orders | insert {qty: 5}")).unwrap(); let missing = stream(&engine, "on orders | group | by region | sum qty as q | end | where region == null"); assert_eq!(missing.len(), 1); assert_eq!(missing[0].get("q"), Some(&Value::from(5_i64))); assert_eq!(names_of_regions(&stream(&engine, "on orders | where status? == \"paid\" | derive t = 1 | where region in [\"EU\", \"US\"]")), ["EU", "EU"]); assert_eq!(stream(&engine, "on orders | union | on orders | where qty > 0 | end | where region? == \"EU\"").len(), 2 * stream(&engine, "on orders | where qty > 0 and region? == \"EU\"").len()); assert!(stream(&engine, "on orders | where qty > 100 | where region == 5").is_empty()); assert!(engine.execute(&pipeline("on orders | where qty > 1 | where region == 5")).is_err()); }
fn names_of_regions(rows: &[Document]) -> Vec<&str> { rows.iter().map(|row| row.get("region").and_then(Value::as_str).unwrap()).collect() }
#[test] fn list_collects_the_values_of_each_group_in_input_order() { let engine = engine(); let rows = stream(&engine, "on orders | derive missing = if(qty > 3, 1, null) | group | by region | list qty as qs | list qty * price where status == \"paid\" as paid | list missing? as m | count as n | end | sort region"); let field = |row: &Document, name: &str| row.get(name).cloned().unwrap(); assert_eq!(rows.iter().map(|row| (field(row, "qs"), field(row, "paid"), field(row, "m"))).collect::<Vec<_>>(), [(Value::array([2_i64, 1].map(Value::from)), Value::array([20_i64, 99].map(Value::from)), Value::array([])), (Value::array([Value::from(4_i64)]), Value::array([]), Value::array([Value::from(1_i64)]))]); assert_eq!(stream(&engine, "on orders | group | by region | list qty as qs | end | unwind qs | count as n")[0].get("n"), Some(&Value::from(3_u64))); }
#[test] fn lookup_stages_after_a_blocking_one_read_the_outer_row() { let engine = engine(); let rows = stream(&engine, "on orders as o | lookup orders as x | group | by region | sum qty as q | end | where region == o.region | into mine | end | derive q = get(at(mine, 0), \"q\") | select region, q"); assert_eq!(rows.iter().map(|row| (row.get("region").cloned().unwrap(), row.get("q").cloned().unwrap())).collect::<Vec<_>>(), [("EU", 3_i64), ("EU", 3), ("US", 4)].map(|(region, q)| (Value::from(region), Value::from(q)))); }
#[test] fn union_branches_take_any_pipeline() { let engine = engine(); let column = |text: &str, field: &str| stream(&engine, text).iter().map(|row| row.get(field).cloned().unwrap()).collect::<Vec<_>>(); for (text, n) in [("on orders | union | on orders | group | by region | sum qty as q | end | end | count as n", 5_u64), ("on orders | union | on orders | sort qty desc | limit 1 | end | count as n", 4), ("on orders | union | on orders | union | on users | end | end | count as n", 9), ("on orders | union | on orders | lookup users as u | where u.age > 18 | into adults | end | end | count as n", 6)] { assert_eq!(column(text, "n"), [Value::from(n)], "{text}"); } assert_eq!(column("on orders | group | by region | sum qty as q | end | union | on orders | group | by region | sum qty as q | end | end | group | by region | sum q as q | end | sort region", "q"), [6_i64, 8].map(Value::from)); engine.execute(&pipeline(r#"on orders | insert {_place: "p", _app_instance: "a", region: "EU", qty: 7}"#)).unwrap(); let planned = engine.plan(&pipeline("on orders | union | on orders | group | by region | sum qty as q | end | end | select q")).unwrap(); let scoped = engine.execute_physical_scoped(planned.physical(), &og_core::query::DocumentScope::new("p", "a")).unwrap(); assert_eq!(scoped.rows().iter().map(|row| row.document().get("q").cloned()).collect::<Vec<_>>(), [None, Some(Value::from(7_i64))]); }
